import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Find features with significant association (p < 0.05)
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('copy_number', 'expression'):
            # Use Welch's t-test approach
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            if len(y0) > 0 and len(y1) > 0:
                t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
                p_val = 2 * (1 - stats.t.cdf(abs(t_stat), len(y0) + len(y1) - 2))
                if p_val < 0.05:
                    sig_features.append((fid, t_stat))

    # Sort by effect size
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates (correlated with |r| >= 0.6)
    keep = []
    excluded = set()
    for i, (fid1, _) in enumerate(sig_features):
        if fid1 in excluded:
            continue
        keep.append(fid1)
        # Check correlations
        for j, (fid2, _) in enumerate(sig_features[i+1:], i+1):
            if fid2 in excluded:
                continue
            corr = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0, 1]
            if abs(corr) >= 0.6:
                excluded.add(fid2)

    # Use top features as potential drivers (at most MAX_DRIVERS)
    drivers = tuple(fid for fid in keep[:MAX_DRIVERS])

    # For logistic regression, use all significant features that aren't drivers
    columns = tuple(fid for fid in keep if fid not in drivers)

    # Look for interaction terms between drivers
    products = []
    for i, d1 in enumerate(drivers):
        for d2 in drivers[i+1:]:
            products.append((d1, d2))

    # Create weighted score from top features
    loadings = {}
    for i, fid in enumerate(keep[:5]):
        # Weight by effect size
        effect = feats.x[:, feats.column(fid)].T @ feats.y
        loadings[fid] = effect

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

